// A compile-check shim: the small slice of tModLoader 1.4.4 that shadw-mod's generated code touches, declared from the public API as documented.
// It exists to catch the mistakes a compiler catches (syntax, types, names, missing usings) on a machine with no tModLoader. It is NOT tModLoader:
// a green check here does not prove the real API accepts the code. The real build is `dotnet build` against a tModLoader install (see docs/TERRARIA.md).
// The vanilla ID tables (ItemID, NPCID, ...) are generated by `shadw-mod content check` from the names the code uses; unknown names are reported as unverified.
using System;
using System.Collections.Generic;
using System.IO;

namespace Microsoft.Xna.Framework
{
    public struct Vector2
    {
        public float X, Y;
        public Vector2(float x, float y) { X = x; Y = y; }
        public static Vector2 Zero => new Vector2(0, 0);
        public static Vector2 UnitY => new Vector2(0, 1);
        public static Vector2 operator +(Vector2 a, Vector2 b) => new Vector2(a.X + b.X, a.Y + b.Y);
        public static Vector2 operator -(Vector2 a, Vector2 b) => new Vector2(a.X - b.X, a.Y - b.Y);
        public static Vector2 operator *(Vector2 a, float k) => new Vector2(a.X * k, a.Y * k);
        public static Vector2 Lerp(Vector2 a, Vector2 b, float t) => a;
    }
    public struct Point { public int X, Y; }
    public struct Rectangle
    {
        public int X, Y, Width, Height;
        public Rectangle(int x, int y, int w, int h) { X = x; Y = y; Width = w; Height = h; }
        public static Rectangle Empty => new Rectangle(0, 0, 0, 0);
        public bool Contains(Point p) => true;
    }
    public struct Color { public Color(int r, int g, int b) { } }
    public static class MathHelper { public const float PiOver2 = 1.5707964f; public const float Pi = 3.1415927f; public static float Lerp(float a, float b, float t) => a; }
}

